class Messenger {
    send(type, payload) {
        const targetWindow = 'function' == typeof this.options.targetWindow ? this.options.targetWindow() : this.options.targetWindow;
        targetWindow.postMessage({
            source: this.options.selfSource,
            type,
            payload
        }, this.options.targetOrigin);
    }
    on(type, handler) {
        let set = this.listeners.get(type);
        if (!set) {
            set = new Set();
            this.listeners.set(type, set);
        }
        set.add(handler);
        return ()=>{
            this.off(type, handler);
        };
    }
    off(type, handler) {
        const set = this.listeners.get(type);
        if (!set) return;
        set.delete(handler);
        if (0 === set.size) this.listeners.delete(type);
    }
    destroy() {
        window.removeEventListener('message', this.boundListener);
        this.listeners.clear();
    }
    handleMessage(event) {
        if ('*' !== this.options.targetOrigin && event.origin !== this.options.targetOrigin) return;
        const { data } = event;
        if (!data?.type || data.source === this.options.selfSource) return;
        const handlers = this.listeners.get(data.type);
        if (!handlers) return;
        handlers.forEach((handler)=>handler(data.payload, data));
    }
    constructor(options){
        this.options = options;
        this.listeners = new Map();
        this.boundListener = this.handleMessage.bind(this);
        window.addEventListener('message', this.boundListener);
    }
}
export { Messenger };
